using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;
namespace Society.Api;
public static class PersonalAccount {
 [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
 public record Write([Required,MaxLength(160)] string FullName,[MaxLength(160)] string? Designation,[MaxLength(30)] string? Phone,[Required] string Revision);
 public static void Map(RouteGroupBuilder api){
 api.MapGet("/users/me/personal-profile",async(AppDb db,Access a)=>{var u=await db.Users.SingleAsync(u=>u.Id==a.UserId);var designation=await db.UserClaims.Where(c=>c.UserId==a.UserId&&c.ClaimType=="personal:designation").Select(c=>c.ClaimValue).FirstOrDefaultAsync();var fullName=u.FullName;var phone=await db.UserClaims.Where(c=>c.UserId==a.UserId&&c.ClaimType=="personal:phone").Select(c=>c.ClaimValue).FirstOrDefaultAsync()??u.PhoneNumber;
 if(fullName.EndsWith(" representative",StringComparison.OrdinalIgnoreCase)){
 fullName="";
 var profiles=await MembershipExperience.Owned(db,a.UserId).Select(m=>m.Profile).ToListAsync();
 foreach(var profile in profiles){var contacts=MembershipService.Json(profile)["contacts"] as System.Text.Json.Nodes.JsonArray;if(contacts==null)continue;var contact=contacts.FirstOrDefault(c=>string.Equals(c?["email"]?.ToString(),u.Email,StringComparison.OrdinalIgnoreCase));if(contact==null)continue;fullName=contact["name"]?.ToString()??"";phone??=contact["mobile"]?.ToString();designation??=contact["designation"]?.ToString();if(!string.IsNullOrWhiteSpace(fullName))break;}
 }
 return Results.Ok(new{fullName,phoneNumber=phone,u.Email,u.EmailConfirmed,designation=designation??"",revision=u.ConcurrencyStamp});}).RequireAuthorization();
 api.MapPut("/users/me/personal-profile",async(Write r,AppDb db,Access a)=>{if(string.IsNullOrWhiteSpace(r.FullName))throw new DomainException("Enter your personal name");await using var tx=await db.Database.BeginTransactionAsync();var u=await db.Users.SingleAsync(u=>u.Id==a.UserId);if(u.ConcurrencyStamp!=r.Revision)return Results.Conflict(new{title="Your profile changed. Refresh before saving."});u.FullName=r.FullName.Trim();var phone=r.Phone?.Trim()??"";var phoneClaim=await db.UserClaims.SingleOrDefaultAsync(c=>c.UserId==a.UserId&&c.ClaimType=="personal:phone");if(phoneClaim==null)db.UserClaims.Add(new Microsoft.AspNetCore.Identity.IdentityUserClaim<Guid>{UserId=a.UserId,ClaimType="personal:phone",ClaimValue=phone});else phoneClaim.ClaimValue=phone;u.ConcurrencyStamp=Guid.NewGuid().ToString();var claim=await db.UserClaims.SingleOrDefaultAsync(c=>c.UserId==a.UserId&&c.ClaimType=="personal:designation");if(claim==null)db.UserClaims.Add(new Microsoft.AspNetCore.Identity.IdentityUserClaim<Guid>{UserId=a.UserId,ClaimType="personal:designation",ClaimValue=r.Designation?.Trim()??""});else claim.ClaimValue=r.Designation?.Trim()??"";db.Audits.Add(new Audit{ActorId=a.UserId,ResourceId=a.UserId,Action="account.personal.profile.updated",Details="{\"scope\":\"Account only; institution identity unchanged\"}"});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();}).RequireAuthorization();
 api.MapGet("/users/me/institutional-profiles",async(AppDb db,Access a)=>{var rows=await(from m in MembershipExperience.Owned(db,a.UserId) join c in db.MembershipCategories on m.CategoryId equals c.Id join p in db.Persons on m.PersonId equals p.Id where c.Kind!="Individual" select new{m.Id,m.Number,p.FullName,c.Kind,m.Profile}).ToListAsync();var email=await db.Users.Where(u=>u.Id==a.UserId).Select(u=>u.NormalizedEmail).SingleAsync();var ids=rows.Select(r=>r.Id).ToArray();var affiliations=await db.Set<OrganizationMember>().Where(r=>ids.Contains(r.MembershipId)&&r.RevokedAt==null&&r.Email==email).ToListAsync();return Results.Ok(rows.Select(r=>{var p=MembershipService.Json(r.Profile);var contact=(p["contacts"] as System.Text.Json.Nodes.JsonArray)?.FirstOrDefault(c=>string.Equals(c?["email"]?.ToString(),email,StringComparison.OrdinalIgnoreCase));return new{r.Id,r.Number,registeredName=r.FullName,r.Kind,affiliationId=affiliations.FirstOrDefault(a=>a.MembershipId==r.Id)?.Number??contact?["memberId"]?.ToString()??contact?["affiliationId"]?.ToString(),institutionType=p["institutionType"]?.ToString()??p["organizationType"]?.ToString()??r.Kind,email=p["email"]?.ToString(),website=p["website"]?.ToString()};}));}).RequireAuthorization();
 }
}
